variable_start = { "{{-" | "{{" }
variable_end   = { "-}}" | "}}" }
// whitespace control
tag_start      = { "{%-" | "{%" }
tag_end        = { "-%}" | "%}" }
comment_start  = { "{#-" | "{#" }
comment_end    = { "-#}" | "#}" }
block_start    = _{ variable_start | tag_start | comment_start }

comment_text       = ${ (!(comment_end) ~ ANY)+ }

